unsafe fn precompute_bonus(
    mut haystack: *const c_char,
    mut match_bonus: *mut score_t,
) {
    let mut last_ch: c_char = '/' as i32 as c_char;
    loop {
        let ch = unsafe { *haystack }; // SAFETY: caller guarantees `haystack` points to a valid NUL-terminated byte string; we read one byte at the current position.
        if ch == 0 {
            break;
        }
        let idx = bonus_index[ch as c_uchar as usize] as usize;
        unsafe {
            *match_bonus = bonus_states[idx][last_ch as c_uchar as usize];
        } // SAFETY: caller guarantees `match_bonus` has space for each non-NUL byte in `haystack`; indices are derived from `u8` values and stay within the lookup tables as in the original code.
        last_ch = ch;
        haystack = unsafe { haystack.add(1) }; // SAFETY: advancing within the same valid NUL-terminated string by one byte after a successful read.
        match_bonus = unsafe { match_bonus.add(1) }; // SAFETY: advancing the output pointer in lockstep with processed input bytes; caller guarantees sufficient capacity.
    }
}

